	using namespace noarr;

	// Tunable parameter: how many 'k' indices per block when streaming A.
	// Adjust this for different cache sizes / architectures if desired.
	constexpr std::size_t K_BLOCK = 32;

	// View of A with the 'k' dimension split into blocks of length K_BLOCK.
	// into_blocks_static handles the case where M is not divisible by K_BLOCK
	// via a "body" and "border" part. The extra tuple-like border dimension
	// and the block index are completely handled by the traverser; we never
	// need to touch them explicitly.
	auto A_blocked = A ^ noarr::into_blocks_static<'k', 'b', 'K', 'k'>(K_BLOCK);

