	// For each (i,j), we iterate over all logical k via for_each on trav_ij,
	// which now internally iterates the ('b','K','k') block dimensions.
	noarr::traverser(C, A_blocked).template for_dims<'i'>([&](auto trav_i) {
		// trav_i has 'i' fixed; remaining dimensions include 'j' (for C)
		// and the blocked k-dimensions ('b','K','k') for A_blocked.
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// State with just the currently fixed ('i','j') indices
			auto s_ij = trav_ij.state();
			auto [i, j] = noarr::get_indices<'i', 'j'>(s_ij);

			// Only update the lower triangle (including the diagonal).
			if (j <= i) {
