				num_t cij = C[s_ij] * beta;

				// Iterate over all k (handled internally as blocks 'K' and
				// possibly a short border) and accumulate:
				//   cij += alpha * A[i,k] * A[j,k]
				//
				// The state 's' provided here contains:
				//   - the fixed ('i','j') we already know,
				//   - plus the block indices produced by into_blocks_static.
				// C ignores k-related indices; A_blocked uses them to
				// reconstruct logical k.
				trav_ij.for_each([&](auto s) {
					// A[i][k]: uses current state's 'i' and k-related indices.
					num_t a_ik = A_blocked[s];

					// To get A[j][k], build a state with the same k indices
					// but with 'i' replaced by 'j'.
					auto s_jk = noarr::update_index<'i'>(s, [=](auto) { return j; });
					num_t a_jk = A_blocked[s_jk];

					cij += alpha * a_ik * a_jk;
				});

				// Write back the final value once.
				C[s_ij] = cij;
			}
		});
	});
	#pragma endscop
}

