	auto A_blocked = A ^ noarr::into_blocks_dynamic<'k', 'K', 'L', 'b'>(k_block_len);

	#pragma scop
	// Outer loop over i (row index of C and A)
	traverser(C, A_blocked).template for_dims<'i'>([&, alpha, beta](auto trav_i) {
