		// to keep the computation restricted to the lower triangle.
		trav_i.template for_dims<'j'>([&, alpha, beta](auto trav_ij) {
			// Obtain the current (i,j) pair from the traverser state
			auto state_ij = trav_ij.state(); // contains fixed indices 'i' and 'j'
			auto [i, j] = get_indices<'i', 'j'>(state_ij);

			// We only update the lower triangle, i.e., j <= i
			if (j > i)
				return;

			// Start from beta * C(i,j)
			num_t acc = beta * C[state_ij];

			// Reduction over the (blocked) k-dimension.
			//
			// trav_ij has 'i' and 'j' fixed; the remaining dimensions come
			// from A_blocked: 'K', 'L', and 'b'. A_blocked ignores 'j',
			// while C ignores 'K', 'L', and 'b'.
			//
			// for_each iterates all valid (K, L, b) combinations. The
			// into_blocks_dynamic structure ensures that each original k
			// is represented exactly once among these states; entries for
			// which 'b' is empty are never traversed.
			trav_ij.for_each([&, alpha, j](auto state) {
				// state has indices ('i', 'j', 'K', 'L', 'b')
				// A_blocked uses ('i', 'K', 'L', 'b') and ignores 'j'.

				// A[i][k] for current k (encoded by K,L,b in state)
