				// A[j][k]: same k, but with i replaced by j.
				// We only change dimension 'i'; other indices, including
				// the blocked k representation, remain identical.
				auto state_jk = noarr::update_index<'i'>(state, [=](auto) { return j; });
				num_t a_jk = A_blocked[state_jk];

				acc += alpha * a_ik * a_jk;
			});

			// Store the final result for this element of the lower triangle
			C[state_ij] = acc;
		});
	});
	#pragma endscop
