constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

struct tuning {
	// C: i x j  (logical), stored with 'j' as the fast-varying (inner) index
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec);
	// A: i x k  (logical), stored with 'k' as the fast-varying (inner) index
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec);
} tuning;

// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Precompute lengths once; they are independent of indices
	auto n_len = A | get_length<'i'>(); // N
	auto m_len = A | get_length<'k'>(); // M

	// A[i][k] = ( (i * k + 1) % n ) / n;
	// Traversal order: i-major, k as inner (contiguous) dimension in A
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	// Traversal order: i-major, j as inner (contiguous) dimension in C
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Optimized for data locality:
// 1) Scale the lower triangle of C by beta in a single pass.
// 2) For each (i,j) in the lower triangle, compute the dot product of
//    the i-th and j-th rows of A (k is the inner / contiguous dimension).
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop
	// --------------------------------------------------------------------
	// 1) Scale C by beta (only the lower triangle, j <= i)
	//    Traversal is i-major, j as inner (contiguous) index in C.
	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		if (j <= i) {
			C[state] *= beta;
		}
	});

	// --------------------------------------------------------------------
	// 2) Symmetric rank-k update on the lower triangle:
	//    For each (i, j) with j <= i:
	//       C[i,j] += alpha * sum_k A[i,k] * A[j,k]
	//
	// We iterate (i,j) explicitly via for_dims<'i','j'> and use for_each
	// on the remaining 'k' dimension. This gives an i-major, j-minor
	// traversal of C, and a k-inner traversal of A (good spatial locality).
	traverser(C, A).template for_dims<'i', 'j'>([&](auto trav_ij) {
		// trav_ij has 'i' and 'j' fixed; remaining free dimension is 'k' (from A)
		auto state_ij = trav_ij.state();
		auto [i, j]   = get_indices<'i', 'j'>(state_ij);

		// Only update the lower triangle
		if (j > i)
			return;

		num_t sum = (num_t)0;

		// for_each over the remaining dimension(s) – here just 'k'.
		// This corresponds to:
		//   for k in 0 .. M-1:
		//       sum += A[i,k] * A[j,k];
		trav_ij.for_each([&](auto state_ijk) {
			// state_ijk carries indices (i, j, k) for the joint traverser.
			// A only uses 'i' and 'k'; 'j' is ignored in this access.
			auto a_ik = A[state_ijk];

			// To get A[j,k], reuse the same 'k' and replace 'i' by 'j'.
			// We perform state arithmetic on the state, not on the traverser,
			// as required by the guidelines.
			auto state_jk = noarr::update_index<'i'>(state_ijk, [=](auto) { return j; });
			auto a_jk     = A[state_jk];

			sum += a_ik * a_jk;
		});

		// C[i,j] was already scaled by beta; now accumulate alpha * (A row i • A row j)
		C[state_ij] += alpha * sum;
	});
	#pragma endscop
}

} // namespace

