	//
	// We compute, for each (i,j) with j <= i:
	//   C[i][j] += alpha * sum_k A[i][k] * A[j][k]
	//
	// To improve cache usage along the k-dimension (which is contiguous in A),
	// we create a blocked view of A in 'k' using into_blocks_dynamic:
	//   - 'K' is the block index (major)
	//   - 'k' is the index within the block (minor)
	//   - 'p' is a presence dimension (length 0 or 1) used to mask the
	//     incomplete tail block; combinations with length 0 in 'p' are never
	//     visited by the traverser.
	// ---------------------------------------------------------------------

	constexpr auto k_block_len = noarr::lit<tuning::k_block>;
	auto A_blocked = A ^ noarr::into_blocks_dynamic<'k', 'K', 'k', 'p'>(k_block_len);

	// Outer parallel-friendly traversal over (i,j).
	// We use for_dims<'i','j'> so that the remaining dimension(s) for the
	// inner for_each are exactly the (blocked) k-dimensions.
	traverser(C, A_blocked).template for_dims<'i', 'j'>([=](auto trav_ij) {
		// trav_ij has 'i' and 'j' fixed; remaining dims: 'K', 'k', 'p'
		auto ij_state = trav_ij.state();
		auto i = get_index<'i'>(ij_state);
		auto j = get_index<'j'>(ij_state);

		// Only work on the lower triangle
		if (j > i)
			return;

		num_t sum = (num_t)0;

		// First iterate over k-blocks (dimension 'K') ...
		trav_ij.template for_dims<'K'>([&](auto trav_ijK) {
			// ... and inside each block iterate over the intra-block
			// index 'k' and the presence dimension 'p'.
			//
			// For indices that lie outside the original range of 'k',
			// 'p' has length 0, so no state is produced and such entries
			// are skipped automatically.
			trav_ijK.for_each([&](auto state) {
				// state contains (i, j, K, k, p)
				// A_blocked expects (i, K, k, p) and ignores 'j'.
				auto a_ik = A_blocked[state]; // A[i][k]

				// Construct a state for A[j][k] by replacing the 'i'
				// index in the current state with j, while keeping
				// (K, k, p) unchanged.
				auto state_j = noarr::update_index<'i'>(state, [=](auto) { return j; });
				auto a_jk = A_blocked[state_j]; // A[j][k]

				sum += a_ik * a_jk;
			});
		});

		// Accumulate the contribution of the full dot product into C(i,j)
		C[trav_ij] += alpha * sum;
	});

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem size
	std::size_t n = N;
	std::size_t m = M;

	// input data
	num_t alpha;
	num_t beta;

	// set lengths for each structure
	auto set_lengths_C = noarr::set_length<'i'>(n) ^ noarr::set_length<'j'>(n);
	auto set_lengths_A = noarr::set_length<'i'>(n) ^ noarr::set_length<'k'>(m);

	// allocate bags
	auto C = noarr::bag(noarr::scalar<num_t>() ^ tuning.c_layout ^ set_lengths_C);
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths_A);

	// initialize data
	init_array(alpha, beta, C.get_ref(), A.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// run kernel
	kernel_syrk(alpha, beta, C.get_ref(), A.get_ref());

	auto end = std::chrono::high_resolution_clock::now();

	auto duration = std::chrono::duration<long double>(end - start);

	// print results (optional)
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		// hoist 'i' to print C in i-major order
		noarr::serialize_data(std::cerr, C.get_ref() ^ noarr::hoist<'i'>());
	}

	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;
}
