// initialization function
void init_array(num_t &alpha, num_t &beta, auto C, auto A) {
	// C: i x j, length(i) = N, length(j) = N
	// A: i x k, length(i) = N, length(k) = M
	using namespace noarr;

	alpha = (num_t)1.5;
	beta = (num_t)1.2;

	// A[i][k] = ( (i * k + 1) % n ) / n;
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		auto n_len = A | get_length<'i'>();
		A[state] = (num_t)((i * k + 1) % n_len) / n_len;
	});

	// C[i][j] = ( (i * j + 2) % m ) / m;
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		auto m_len = A | get_length<'k'>(); // use A's second dimension length (M)
		C[state] = (num_t)((i * j + 2) % m_len) / m_len;
	});
}

// computation kernel
//
// BLAS SYRK:
//   C := alpha * A * A^T + beta * C
// A is N x M (i x k)
// C is N x N (i x j), lower triangle (j <= i) updated
//
// Layout recap:
//
//   C: scalar<num_t> ^ vector<'j'>(N) ^ vector<'i'>(N)
//      => 'j' is outer, 'i' is inner (C(i,j) is contiguous in 'i' for fixed j)
//
//   A: scalar<num_t> ^ vector<'k'>(M) ^ vector<'i'>(N)
//      => 'k' is outer, 'i' is inner (A(i,k) is contiguous in 'i' for fixed k)
//
// Optimized traversal strategy:
//
// 1) Scale the lower triangle of C by beta.
//    We traverse C with 'j' fixed and iterate over 'i' in the innermost
//    loop. This touches C(i,j) with unit stride along 'i', matching the
//    physical layout.
//
// 2) Rank-k update: C := C + alpha * A * A^T (lower triangle only).
//
//    We iterate dimensions in the order k -> j -> i:
//
//      - Outer loop over k (columns of A).
//      - Middle loop over j (row index for A(j,k) and column index of C).
//      - Inner loop over i (row index for C and A(i,k)).
//
//    For each fixed (k, j):
//      - Preload a_jk = A(j, k) once.
//      - Sweep i in the innermost loop; for i >= j we update:
//
//          C(i, j) += alpha * A(i, k) * a_jk
//
//    This achieves:
//      * unit-stride access to A(i,k) along 'i'
//      * unit-stride updates to C(i,j) along 'i'
//      * only the lower triangle (j <= i) is touched, as required.
//
[[gnu::flatten, gnu::noinline]]
void kernel_syrk(num_t alpha, num_t beta, auto C, auto A) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Scale C by beta on its lower triangle (j <= i)
	// ------------------------------------------------------------------
	//
	// We traverse C in j-major / i-minor order:
	//   - for_dims<'j'> fixes j (column),
	//   - for_each then iterates over i (row) with unit stride.
	traverser(C).template for_dims<'j'>([&](auto trav_j) {
		trav_j.for_each([&](auto state) {
			auto [i, j] = get_indices<'i', 'j'>(state);
			if (j <= i) {
				C[state] *= beta;
			}
		});
	});

	// ------------------------------------------------------------------
	// 2) Rank-k update: C += alpha * A * A^T on the lower triangle
	// ------------------------------------------------------------------
	//
	// Use a combined traverser over C and A so that states always contain
	// all needed indices ('i', 'j', 'k').
	//
	// Outer:  k  (dimension of A)
	// Middle: j  (column of C, row index for A(j,k))
	// Inner:  i  (row in C and A, swept with unit stride)
	traverser(C, A).template for_dims<'k'>([&](auto trav_k) {
		// Fix k (one column of A)
		trav_k.template for_dims<'j'>([&](auto trav_kj) {
			// trav_kj has k and j fixed; i is still free.

			// State with indices for (j, k) but without 'i'.
			auto state_kj = trav_kj.state();
			auto j_idx = get_index<'j'>(state_kj);

			// Build a state for A(j, k):
			//   start from (j, k) state and add i = j.
			auto state_jk = state_kj + idx<'i'>(j_idx);
			const num_t a_jk = A[state_jk];

			// Now sweep i in the innermost loop.
			// trav_kj.for_each(...) iterates over the remaining dimension(s),
			// here 'i'. This leads to unit-stride access in 'i' for both
			// A(i,k) and C(i,j).
			trav_kj.for_each([&](auto state) {
				auto i = get_index<'i'>(state);

				// Only update the lower triangle: j <= i.
				if (i >= j_idx) {
					const num_t a_ik = A[state]; // uses i,k from 'state' (extra 'j' is ignored)
					C[state] += alpha * a_ik * a_jk;
				}
			});
		});
	});

	#pragma endscop
}

} // namespace

